function renderDp(){dpSummary.textContent=tr('เพิ่ม Dianping หน้าร้านตรงแล้ว 11 จาก 12 ร้านที่เพิ่มเติมจากลิงก์เดิม ตรวจชื่อร้านและเมืองเมื่อ 6 ต.ค. 2026 เหลือ雪域旅途牦牛肉火锅ที่ค้นใน理县แล้วยังไม่พบรายการตรง จึงให้ลิงก์ค้นหาและระบุสถานะไว้','已补充原有链接以外12家中的11家大众点评门店直达，2026年10月6日核对店名与城市。雪域旅途牦牛肉火锅在理县搜索仍未找到匹配门店，保留搜索入口并标注待核实。');for(const {node,shop:s} of dpTargets){node.innerHTML=s.id?`<p>${tr('Dianping · พบรายการตรงชื่อร้าน/สาขา','大众点评 · 已找到匹配店名/分店')}</p><div class="maplinks"><a class="app-link" href="dianping://shopinfo?${s.numeric?'id':'shopuuid'}=${s.id}">${tr('Dianping · เปิดแอปร้านนี้','大众点评 · 打开此店')}</a><a target="_blank" rel="noopener" href="https://m.dianping.com/${s.numeric?'shop':'shopinfo'}/${s.id}">${tr('Dianping · หน้าร้าน','大众点评 · 门店页')}</a><a target="_blank" rel="noopener" href="${s.numeric?'https://m.dianping.com/shop/'+s.id:'https://www.dianping.com/shop/'+s.id}">${tr('หลักฐานรายการร้าน','门店匹配来源')}</a></div>`:`<p>${tr('Dianping · ยังไม่พบหน้าร้านที่ยืนยันตรงสาขา','大众点评 · 尚未核实准确门店页')}</p><div class="maplinks"><button data-dp-copy="${esc(s.name+' '+s.city)}">${tr('คัดลอกชื่อ + เมืองไปค้นใน Dianping','复制店名+城市到点评搜索')}</button><a target="_blank" rel="noopener" href="https://www.dianping.com/search/keyword/1696/0_${encodeURIComponent(s.name)}">${tr('ค้นใน Dianping (ยังไม่ใช่หน้าร้าน)','在点评搜索（非门店直达）')}</a></div>`;}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-dp-copy]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.dpCopy);b.textContent=tr('คัดลอกแล้ว ✓','已复制 ✓')}catch{window.prompt(tr('คัดลอกข้อความนี้ไปค้นใน Dianping','复制以下文字到大众点评搜索'),b.dataset.dpCopy)}});
